) AS v(id, k, gd_num, so_id, gd_id, so_no, gd_no, customer_id, remarks, remarks_2, di_shipping_method)
  CROSS JOIN (SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(x.packing_no, '-', 3), '-', -1) AS UNSIGNED)), 0)
         + IF(DATE(CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+08:00')) <= '2026-10-13', 500, 0) AS base
    FROM packing x WHERE x.tenant_id = '128671' AND x.packing_no LIKE 'PACK-20261013-%'
      AND ((x.id >> 12) & 1023) <> 1001) n
  WHERE NOT EXISTS (SELECT 1 FROM packing x WHERE x.id = v.id)
    AND NOT EXISTS (SELECT 1 FROM packing x WHERE x.gd_id = v.gd_id AND x.is_deleted = 0)
    AND EXISTS (SELECT 1 FROM goods_delivery g WHERE g.id = v.gd_num AND g.tenant_id = '128671'
                AND g.gd_status = 'Created' AND g.is_deleted = 0)
